STORY_CATALOG["kite16"]={"id":"kite16","number":4,"titles":{"th":"อาณาจักรว่าวกระดาษ","en":"The Paper Kite Kingdom","es":"El reino de las cometas de papel","zh":"纸风筝王国","ja":"紙だこの王国","ko":"종이연 왕국","vi":"Vương quốc diều giấy","id":"Kerajaan Layang-Layang Kertas","ms":"Kerajaan Layang-Layang Kertas","fil":"Ang Kaharian ng mga Saranggolang Papel","hi":"काग़ज़ी पतंगों का राज्य","ar":"مملكة الطائرات الورقية","fr":"Le royaume des cerfs-volants en papier","de":"Das Königreich der Papierdrachen","it":"Il regno degli aquiloni di carta","pt":"O reino das pipas de papel","ru":"Королевство бумажных змеев","tr":"Kâğıt Uçurtmalar Krallığı","pl":"Królestwo papierowych latawców","nl":"Het rijk van de papieren vliegers","uk":"Королівство паперових зміїв"},"locales":{"th":[["ลานกว้างหน้าร้อน","พบต้นกับว่าวจุฬา","ต้นทำว่าวจุฬาสีแดงทองด้วยตัวเอง แล้วนำไปเล่นที่ลานกว้าง","แต่วันนี้ลมนิ่งสนิท ว่าวทุกตัวตกลงพื้น","#3a7aa8"],["ว่าวที่พูดได้","ฟังเสียงว่าว","จู่ ๆ ว่าวจุฬาก็กระซิบ \"สายลมหน้าร้อนขาดแล้ว ช่วยเราด้วย\"","\"จับสายป่านไว้ให้แน่น เราจะพาเธอไป\"","#3a7aa8"],["ลอยขึ้นฟ้า","บินขึ้นเหนือเมฆ","ว่าวพาต้นลอยขึ้นสูงเหนือหลังคาบ้านและยอดไม้","ลานกว้างข้างล่างเล็กลงจนเหมือนผ้าเช็ดหน้า","#3a7aa8"],["ประตูเมฆ","เข้าสู่อาณาจักร","เหนือเมฆมีประตูใหญ่ที่ทำจากกระดาษสีต่าง ๆ","ว่าวเฝ้าประตูโค้งต้อนรับแขกจากพื้นดิน","#3a7aa8"],["เมืองว่าวปักเป้า","เยี่ยมเมืองแรก","เมืองแรกเต็มไปด้วยว่าวปักเป้าตัวเล็กที่ว่องไว","พวกมันเต้นรำบนสายลมเบา ๆ ที่เหลืออยู่","#c0663a"],["เมืองว่าวมังกร","ขอความช่วยเหลือ","ต่อมาคือเมืองของว่าวมังกรยาวเหยียดหลากสี","มังกรผู้เฒ่าบอกว่า สายลมขาดที่ยอดภูเขาเมฆ","#c0663a"],["เมืองว่าวปลา","รวบรวมของซ่อม","ว่าวรูปปลาจากทั่วโลกมอบด้ายสีรุ้งให้ต้น","\"ใช้ด้ายนี้มัดสายลมให้ติดกันนะ\"","#c0663a"],["เมืองว่าวนก","หาเพื่อนร่วมทาง","ว่าวนกอินทรีตัวใหญ่อาสาพาต้นบินไปยังภูเขาเมฆ","ว่าวจุฬาของต้นบินเคียงข้างอย่างภูมิใจ","#c0663a"],["ทะเลเมฆ","บินข้ามทะเลเมฆ","ทั้งหมดบินข้ามทะเลเมฆที่นุ่มฟูเหมือนสำลี","รุ้งกินน้ำโค้งเป็นสะพานอยู่ข้างหน้า","#4f8a6a"],["ลมหมุนจอมซน","ฝ่าลมหมุน","ลมหมุนจอมซนพุ่งเข้ามาพยายามพันสายป่าน","ต้นหมุนตัวตามลมจนหลุดออกมาได้","#4f8a6a"],["ยอดภูเขาเมฆ","ไปถึงจุดหมาย","บนยอดภูเขาเมฆ มีสายลมสีฟ้าใสขาดออกเป็นสองท่อน","ปลายทั้งสองข้างโบกสะบัดอย่างอ่อนแรง","#4f8a6a"],["มัดสายลม","ซ่อมสายลม","ต้นใช้ด้ายสีรุ้งมัดสายลมสองท่อนเข้าด้วยกันอย่างตั้งใจ","ปมสุดท้ายแน่นหนาดี","#4f8a6a"],["ลมหน้าร้อนกลับมา","ปลุกสายลม","สายลมหายใจเฮือกใหญ่ แล้วพัดออกไปทั่วฟ้า","ว่าวทุกตัวในอาณาจักรลอยขึ้นพร้อมกัน","#7a4fa0"],["ขบวนว่าวฉลอง","ร่วมขบวนแห่","อาณาจักรจัดขบวนว่าวยาวที่สุดเพื่อขอบคุณต้น","ว่าวจากทุกเมืองบินเรียงกันเป็นสายรุ้ง","#7a4fa0"],["ร่อนกลับลงมา","กลับสู่พื้นดิน","สายลมอุ่น ๆ พาต้นร่อนกลับลงมาอย่างนุ่มนวล","เพื่อน ๆ ที่ลานกว้างร้องเฮ เมื่อว่าวทุกตัวลอยได้อีกครั้ง","#7a4fa0"],["ว่าวของทุกคน","แบ่งปันท้องฟ้า","ต้นสอนเพื่อน ๆ ทำว่าวของตัวเอง ฟ้าเต็มไปด้วยสีสัน","สิ่งที่เราสร้างด้วยมือและใจ สามารถพาเราไปได้ไกล จบ","#7a4fa0"]],"en":[["The Summer Field","Meet Ton and his kite","Ton made a red-and-gold star kite all by himself and takes it to the big field.","But today there is no wind, and every kite falls down.","#3a7aa8"],["The Talking Kite","Listen to the kite","Suddenly the kite whispers, \"The summer wind is broken. Please help us.\"","\"Hold the string tight, and we will take you there.\"","#3a7aa8"],["Up into the Sky","Fly above the clouds","The kite lifts Ton high above the rooftops and treetops.","The field below shrinks to the size of a handkerchief.","#3a7aa8"],["The Cloud Gate","Enter the kingdom","Above the clouds stands a great gate made of coloured paper.","The guard kites bow to welcome a guest from the ground.","#3a7aa8"],["The Pakpao City","Visit the first city","The first city is full of small, quick pakpao kites.","They dance on the last gentle breezes left.","#c0663a"],["The Dragon Kite City","Ask for help","Next comes a city of long, colourful dragon kites.","The eldest dragon says the wind broke at the top of Cloud Mountain.","#c0663a"],["The Fish Kite City","Gather mending tools","Fish-shaped kites from around the world give Ton a rainbow thread.","\"Use this thread to tie the wind back together.\"","#c0663a"],["The Bird Kite City","Find a travel partner","A big eagle kite offers to fly Ton to Cloud Mountain.","Ton’s star kite flies proudly beside them.","#c0663a"],["The Sea of Clouds","Cross the cloud sea","They fly over a sea of clouds as soft as cotton.","A rainbow arches ahead like a bridge.","#4f8a6a"],["The Mischievous Whirlwind","Get past the whirlwind","A mischievous whirlwind rushes in and tries to tangle the strings.","Ton spins with it and slips free.","#4f8a6a"],["Cloud Mountain Peak","Reach the goal","At the top of Cloud Mountain, a clear blue ribbon of wind lies broken in two.","Both ends flutter weakly.","#4f8a6a"],["Tying the Wind","Mend the wind","Ton carefully ties the two pieces of wind together with the rainbow thread.","The last knot is tight and strong.","#4f8a6a"],["The Summer Wind Returns","Wake the wind","The wind takes a huge breath and blows across the whole sky.","Every kite in the kingdom rises at once.","#7a4fa0"],["The Kite Parade","Join the parade","The kingdom holds its longest kite parade to thank Ton.","Kites from every city line up like a rainbow.","#7a4fa0"],["Gliding Home","Return to the ground","A warm breeze carries Ton gently back down.","His friends in the field cheer as all their kites fly again.","#7a4fa0"],["Kites for Everyone","Share the sky","Ton teaches his friends to make their own kites, and the sky fills with colour.","What we make with our hands and hearts can take us far. The End.","#7a4fa0"]],"es":[["El campo de verano","Conoce a Ton y su cometa","Ton hizo él solo una cometa de estrella roja y dorada y la lleva al campo.","Pero hoy no hay viento y todas las cometas caen.","#3a7aa8"],["La cometa que habla","Escucha a la cometa","De pronto la cometa susurra: \"El viento del verano se rompió. Ayúdanos\".","\"Agarra fuerte el hilo y te llevaremos\".","#3a7aa8"],["Hacia el cielo","Vuela sobre las nubes","La cometa eleva a Ton por encima de tejados y árboles.","El campo de abajo parece un pañuelo.","#3a7aa8"],["La puerta de nubes","Entra en el reino","Sobre las nubes hay una gran puerta de papel de colores.","Las cometas guardianas saludan al invitado de la tierra.","#3a7aa8"],["La ciudad pakpao","Visita la primera ciudad","La primera ciudad está llena de pequeñas cometas pakpao.","Bailan sobre las últimas brisas suaves.","#c0663a"],["La ciudad de los dragones","Pide ayuda","Luego llega una ciudad de largas cometas dragón de colores.","El dragón más viejo dice que el viento se rompió en la Montaña de Nubes.","#c0663a"],["La ciudad de los peces","Reúne herramientas","Cometas con forma de pez de todo el mundo le dan a Ton un hilo arcoíris.","\"Usa este hilo para atar el viento\".","#c0663a"],["La ciudad de los pájaros","Busca compañero","Una gran cometa águila se ofrece a llevar a Ton a la montaña.","La cometa estrella de Ton vuela orgullosa a su lado.","#c0663a"],["El mar de nubes","Cruza el mar de nubes","Vuelan sobre un mar de nubes suave como algodón.","Un arcoíris se curva delante como un puente.","#4f8a6a"],["El remolino travieso","Esquiva el remolino","Un remolino travieso intenta enredar los hilos.","Ton gira con él y logra escapar.","#4f8a6a"],["La cima de la montaña","Llega a la meta","En la cima, una cinta azul de viento está partida en dos.","Los dos extremos se agitan débilmente.","#4f8a6a"],["Atar el viento","Repara el viento","Ton ata con cuidado las dos partes del viento con el hilo arcoíris.","El último nudo queda firme.","#4f8a6a"],["Vuelve el viento","Despierta al viento","El viento respira hondo y sopla por todo el cielo.","Todas las cometas del reino se elevan a la vez.","#7a4fa0"],["El desfile de cometas","Únete al desfile","El reino organiza su desfile más largo para dar las gracias a Ton.","Cometas de todas las ciudades forman un arcoíris.","#7a4fa0"],["Planeando a casa","Vuelve a tierra","Una brisa cálida baja a Ton suavemente.","Sus amigos aplauden al ver volar de nuevo sus cometas.","#7a4fa0"],["Cometas para todos","Comparte el cielo","Ton enseña a sus amigos a hacer cometas y el cielo se llena de color.","Lo que hacemos con manos y corazón nos lleva lejos. Fin.","#7a4fa0"]],"zh":[["夏天的草地","认识小东和他的风筝","小东亲手做了一只红金色的星星风筝，带着它来到大草地。","可是今天一点风也没有，所有的风筝都掉了下来。","#3a7aa8"],["会说话的风筝","听风筝说话","忽然，风筝小声说：“夏天的风坏了，请帮帮我们。”","“抓紧线，我们带你去。”","#3a7aa8"],["飞上天空","飞到云上","风筝带着小东飞过屋顶和树梢，越飞越高。","下面的草地变得像手帕一样小。","#3a7aa8"],["云之门","进入王国","云朵上面有一座彩色纸做的大门。","守门的风筝们鞠躬，欢迎来自地面的客人。","#3a7aa8"],["八角风筝城","参观第一座城","第一座城里满是灵巧的小八角风筝。","它们在最后几阵轻风里跳舞。","#c0663a"],["龙风筝城","请求帮助","接下来是长长的彩色龙风筝之城。","最老的龙说，风在云山的山顶断掉了。","#c0663a"],["鱼风筝城","收集修补的东西","来自世界各地的鱼风筝送给小东一根彩虹线。","“用它把风重新系起来吧。”","#c0663a"],["鸟风筝城","找到旅伴","一只大鹰风筝说要带小东去云山。","小东的星星风筝骄傲地飞在旁边。","#c0663a"],["云海","飞越云海","他们飞过一片像棉花一样软的云海。","前方，一道彩虹弯弯的，像一座桥。","#4f8a6a"],["调皮的旋风","逃离旋风","一阵调皮的旋风呼呼地吹来，想把风筝线缠在一起。","小东跟着它一起转，挣脱了出来。","#4f8a6a"],["云山山顶","到达目的地","山顶上躺着一条亮蓝色的风之丝带，断成了两半。","两头都在无力地飘动。","#4f8a6a"],["系好风","修好风","小东用彩虹线，小心地把两段风系在一起。","最后一个结系得牢牢的。","#4f8a6a"],["夏天的风回来了","唤醒风","风深深地吸了一口气，吹遍了整个天空。","王国里所有的风筝一起飞了起来。","#7a4fa0"],["风筝大游行","加入游行","王国举行了最长的风筝游行来感谢小东。","各个城市的风筝连在一起，组成了一道彩虹。","#7a4fa0"],["飘回地面","回到地面","一阵暖暖的微风轻轻把小东送了下来。","所有的风筝又飞起来了，朋友们高兴地欢呼。","#7a4fa0"],["人人都有风筝","分享天空","小东教朋友们自己做风筝，天空变得五彩缤纷。","用双手和真心做出的东西，能带我们飞得很远。完。","#7a4fa0"]],"ja":[["夏の野原","トンとたこに会おう","トンは自分で作った赤と金の星のたこを持って、広い野原へやってきました。","でも今日は風がなく、たこはみんな落ちてしまいます。","#3a7aa8"],["しゃべるたこ","たこの話を聞こう","とつぜん、たこがささやきました。「夏の風がこわれちゃったの。助けて」","「糸をしっかりにぎって。つれていってあげる」","#3a7aa8"],["空へ","雲の上まで飛ぼう","たこはトンを、屋根や木のてっぺんよりずっと高く持ち上げました。","下の野原がハンカチみたいに小さくなります。","#3a7aa8"],["雲の門","王国に入ろう","雲の上に、色とりどりの紙でできた大きな門があります。","見はりのたこたちが、地上からのお客さんにおじぎをしてむかえます。","#3a7aa8"],["パクパオの町","最初の町をたずねよう","最初の町は、小さくてすばしこいパクパオだこでいっぱい。","さいごのやさしいそよ風にのって、おどっています。","#c0663a"],["ドラゴンの町","助けをたのもう","つぎは、長くてカラフルなドラゴンだこの町です。","いちばん年取ったドラゴンが、雲の山のてっぺんで風がちぎれたと教えてくれました。","#c0663a"],["魚の町","なおす道具を集めよう","世界じゅうの魚だこが、トンににじ色の糸をくれました。","「これで風をむすびなおしてね」","#c0663a"],["鳥の町","旅のなかまを見つけよう","大きなワシのたこが、トンを雲の山まで乗せていこうと言ってくれました。","トンの星のたこも、ほこらしげにならんで飛びます。","#c0663a"],["雲の海","雲の海をわたろう","わたのようにふわふわの雲の海の上を飛んでいきます。","前のほうに、にじが橋のようにかかっています。","#4f8a6a"],["いたずらなつむじ風","つむじ風からにげよう","いたずらなつむじ風がびゅうっと来て、糸をからませようとします。","トンはいっしょにくるくる回って、ぬけ出しました。","#4f8a6a"],["雲の山のてっぺん","目的地につこう","てっぺんには、まっぷたつにちぎれた明るい青の風のリボンがありました。","両はしが弱々しくはためいています。","#4f8a6a"],["風をむすぶ","風をなおそう","トンはにじ色の糸で、ふたつの風をていねいにむすびました。","さいごのむすび目も、しっかりとまりました。","#4f8a6a"],["夏の風が帰ってきた","風を目ざめさせよう","風は大きく息をすって、空いっぱいにふきわたりました。","王国じゅうのたこが、いっせいにまい上がります。","#7a4fa0"],["たこのパレード","パレードに参加しよう","王国は、トンにありがとうを言うために、いちばん長いたこのパレードをひらきました。","すべての町のたこが、ならんでにじをつくります。","#7a4fa0"],["ふわりと帰る","地上へもどろう","あたたかいそよ風が、トンをそっと下までおろしてくれました。","たこがまた飛ぶのを見て、友だちが大よろこび。","#7a4fa0"],["みんなのたこ","空をわけあおう","トンは友だちに、自分でたこを作る方法を教え、空はカラフルになりました。","手と心で作ったものは、わたしたちを遠くまでつれていってくれます。おしまい。","#7a4fa0"]],"ko":[["여름 들판","톤과 연을 만나요","톤은 직접 만든 빨강·금색 별 연을 들고 넓은 들판에 왔어요.","그런데 오늘은 바람이 없어서 연들이 모두 떨어져요.","#3a7aa8"],["말하는 연","연의 말을 들어요","갑자기 연이 속삭여요. “여름 바람이 고장 났어. 우릴 도와줘.”","“줄을 꽉 잡아. 우리가 데려다줄게.”","#3a7aa8"],["하늘로","구름 위로 날아요","연이 톤을 지붕과 나무 꼭대기보다 훨씬 높이 들어 올려요.","아래 들판이 손수건만큼 작아져요.","#3a7aa8"],["구름 문","왕국에 들어가요","구름 위에 알록달록한 종이로 만든 커다란 문이 서 있어요.","문지기 연들이 땅에서 온 손님에게 인사해요.","#3a7aa8"],["빡빠오 도시","첫 번째 도시에 가요","첫 번째 도시는 작고 날쌘 빡빠오 연으로 가득해요.","마지막 부드러운 바람을 타고 춤을 춰요.","#c0663a"],["용 도시","도움을 청해요","다음은 길고 화려한 용 연의 도시예요.","가장 나이 많은 용이 구름산 꼭대기에서 바람이 끊어졌다고 알려 줘요.","#c0663a"],["물고기 도시","고칠 재료를 모아요","세계 곳곳에서 온 물고기 연들이 톤에게 무지개 실을 줘요.","“이걸로 바람을 다시 묶어 줘.”","#c0663a"],["새 도시","길동무를 찾아요","커다란 독수리 연이 톤을 구름산까지 태워 주겠대요.","톤의 별 연도 자랑스럽게 나란히 날아요.","#c0663a"],["구름 바다","구름 바다를 건너요","솜처럼 폭신한 구름 바다 위를 날아가요.","앞쪽에 무지개가 다리처럼 걸려 있어요.","#4f8a6a"],["장난꾸러기 회오리바람","회오리바람에서 벗어나요","장난꾸러기 회오리바람이 휘이잉 불어와 줄을 엉키게 하려고 해요.","톤은 같이 빙글빙글 돌다가 빠져나와요.","#4f8a6a"],["구름산 꼭대기","목적지에 도착해요","꼭대기에는 반으로 끊어진 새파란 바람 리본이 놓여 있어요.","양쪽 끝이 힘없이 펄럭여요.","#4f8a6a"],["바람 묶기","바람을 고쳐요","톤은 무지개 실로 바람 두 조각을 정성껏 묶어요.","마지막 매듭도 단단히 묶였어요.","#4f8a6a"],["여름 바람이 돌아왔어요","바람을 깨워요","바람이 크게 숨을 들이쉬고 온 하늘로 불어 가요.","왕국의 모든 연이 한꺼번에 날아올라요.","#7a4fa0"],["연 행진","행진에 함께해요","왕국은 톤에게 고마움을 전하려고 가장 긴 연 행진을 열어요.","모든 도시의 연이 모여 무지개를 만들어요.","#7a4fa0"],["살랑살랑 땅으로","땅으로 돌아가요","따뜻한 산들바람이 톤을 살며시 내려 줘요.","연들이 다시 날자 친구들이 환호해요.","#7a4fa0"],["모두의 연","하늘을 나눠요","톤은 친구들에게 연 만드는 법을 가르쳐 주고, 하늘이 알록달록해져요.","손과 마음으로 만든 것은 우리를 멀리 데려가 줄 수 있어요. 끝.","#7a4fa0"]],"vi":[["Cánh đồng mùa hè","Làm quen với Ton và con diều","Ton tự làm một con diều ngôi sao đỏ vàng và mang nó ra cánh đồng rộng.","Nhưng hôm nay không có gió, con diều nào cũng rơi xuống.","#3a7aa8"],["Con diều biết nói","Lắng nghe con diều","Bỗng con diều thì thầm: “Gió mùa hè bị hỏng rồi. Giúp chúng tớ với.”","“Cầm chặt dây nhé, chúng tớ sẽ đưa cậu đến đó.”","#3a7aa8"],["Bay lên trời","Bay lên trên mây","Con diều nâng Ton bay cao qua mái nhà và ngọn cây.","Cánh đồng bên dưới nhỏ như chiếc khăn tay.","#3a7aa8"],["Cổng mây","Vào vương quốc","Trên mây có một cánh cổng lớn làm bằng giấy màu.","Những con diều gác cổng cúi chào vị khách đến từ mặt đất.","#3a7aa8"],["Thành phố diều pakpao","Ghé thăm thành phố đầu tiên","Thành phố đầu tiên đầy những con diều pakpao nhỏ nhắn, nhanh nhẹn.","Chúng nhảy múa trên những làn gió nhẹ cuối cùng.","#c0663a"],["Thành phố diều rồng","Nhờ giúp đỡ","Tiếp theo là thành phố của những con diều rồng dài và rực rỡ.","Con rồng già nhất nói gió đã đứt trên đỉnh Núi Mây.","#c0663a"],["Thành phố diều cá","Thu thập đồ để sửa","Diều cá từ khắp nơi trên thế giới tặng Ton một sợi chỉ cầu vồng.","“Dùng nó buộc gió lại nhé.”","#c0663a"],["Thành phố diều chim","Tìm bạn đồng hành","Một con diều đại bàng lớn ngỏ ý chở Ton lên Núi Mây.","Diều ngôi sao của Ton bay bên cạnh đầy tự hào.","#c0663a"],["Biển mây","Bay qua biển mây","Họ bay qua một biển mây mềm như bông.","Phía trước, cầu vồng cong cong như một cây cầu.","#4f8a6a"],["Cơn lốc tinh nghịch","Thoát khỏi cơn lốc","Một cơn lốc tinh nghịch ào tới, định làm rối dây diều.","Ton xoay vòng cùng nó rồi thoát ra.","#4f8a6a"],["Đỉnh Núi Mây","Đến đích","Trên đỉnh có một dải ruy băng gió xanh biếc bị đứt làm đôi.","Hai đầu phấp phới yếu ớt.","#4f8a6a"],["Buộc gió","Sửa lại gió","Ton dùng sợi chỉ cầu vồng cẩn thận buộc hai mảnh gió lại.","Nút thắt cuối cùng thật chắc chắn.","#4f8a6a"],["Gió mùa hè trở lại","Đánh thức gió","Gió hít một hơi thật sâu và thổi khắp bầu trời.","Mọi con diều trong vương quốc cùng bay lên.","#7a4fa0"],["Cuộc diễu hành diều","Tham gia diễu hành","Vương quốc tổ chức cuộc diễu hành diều dài nhất để cảm ơn Ton.","Diều từ mọi thành phố cùng nhau tạo thành cầu vồng.","#7a4fa0"],["Bay về","Trở về mặt đất","Một làn gió ấm nhẹ nhàng đưa Ton xuống.","Các bạn reo hò khi mọi con diều lại bay lên.","#7a4fa0"],["Diều cho mọi người","Chia sẻ bầu trời","Ton dạy các bạn tự làm diều, bầu trời rực rỡ sắc màu.","Những gì ta làm bằng đôi tay và trái tim có thể đưa ta đi thật xa. Hết.","#7a4fa0"]],"id":[["Padang musim panas","Kenalan dengan Ton dan layang-layangnya","Ton membuat sendiri layang-layang bintang merah keemasan dan membawanya ke padang luas.","Tapi hari ini tidak ada angin, dan semua layang-layang jatuh.","#3a7aa8"],["Layang-layang yang bisa bicara","Dengarkan layang-layang","Tiba-tiba layang-layang berbisik, “Angin musim panas rusak. Tolong bantu kami.”","“Pegang talinya erat-erat, kami akan membawamu ke sana.”","#3a7aa8"],["Ke langit","Terbang di atas awan","Layang-layang mengangkat Ton tinggi di atas atap dan puncak pohon.","Padang di bawah tampak sekecil sapu tangan.","#3a7aa8"],["Gerbang awan","Masuk ke kerajaan","Di atas awan berdiri gerbang besar dari kertas warna-warni.","Layang-layang penjaga membungkuk menyambut tamu dari bumi.","#3a7aa8"],["Kota pakpao","Kunjungi kota pertama","Kota pertama penuh layang-layang pakpao yang kecil dan lincah.","Mereka menari di atas embusan angin lembut terakhir.","#c0663a"],["Kota naga","Minta bantuan","Berikutnya kota layang-layang naga yang panjang dan berwarna-warni.","Naga tertua berkata angin putus di puncak Gunung Awan.","#c0663a"],["Kota ikan","Kumpulkan bahan perbaikan","Layang-layang ikan dari seluruh dunia memberi Ton benang pelangi.","“Ikat angin itu lagi dengan benang ini.”","#c0663a"],["Kota burung","Temukan teman seperjalanan","Sebuah layang-layang elang besar menawarkan diri membawa Ton ke Gunung Awan.","Layang-layang bintang Ton terbang bangga di sampingnya.","#c0663a"],["Lautan awan","Seberangi lautan awan","Mereka terbang di atas lautan awan yang lembut seperti kapas.","Di depan, pelangi melengkung seperti jembatan.","#4f8a6a"],["Angin puting beliung yang jahil","Lolos dari puting beliung","Angin puting beliung yang jahil datang dan mencoba membuat tali kusut.","Ton berputar bersamanya lalu berhasil lepas.","#4f8a6a"],["Puncak Gunung Awan","Capai tujuan","Di puncak tergeletak pita angin biru terang yang putus jadi dua.","Kedua ujungnya berkibar lemah.","#4f8a6a"],["Mengikat angin","Perbaiki angin","Dengan benang pelangi, Ton hati-hati mengikat dua potong angin.","Simpul terakhir terikat kuat.","#4f8a6a"],["Angin musim panas kembali","Bangunkan angin","Angin menarik napas dalam-dalam dan bertiup ke seluruh langit.","Semua layang-layang di kerajaan terbang bersamaan.","#7a4fa0"],["Parade layang-layang","Ikut parade","Kerajaan mengadakan parade layang-layang terpanjang untuk berterima kasih kepada Ton.","Layang-layang dari semua kota bersama-sama membentuk pelangi.","#7a4fa0"],["Melayang turun","Kembali ke bumi","Angin hangat menurunkan Ton dengan lembut.","Teman-temannya bersorak saat semua layang-layang terbang lagi.","#7a4fa0"],["Layang-layang untuk semua","Berbagi langit","Ton mengajari teman-temannya membuat layang-layang sendiri, dan langit penuh warna.","Apa yang kita buat dengan tangan dan hati bisa membawa kita jauh. Tamat.","#7a4fa0"]],"ms":[["Padang musim panas","Berkenalan dengan Ton dan layang-layangnya","Ton membuat sendiri layang-layang bintang merah keemasan dan membawanya ke padang yang luas.","Tetapi hari ini tiada angin, dan semua layang-layang jatuh.","#3a7aa8"],["Layang-layang yang bercakap","Dengar kata layang-layang","Tiba-tiba layang-layang itu berbisik, “Angin musim panas sudah rosak. Tolong bantu kami.”","“Pegang tali kuat-kuat, kami akan bawa kamu ke sana.”","#3a7aa8"],["Ke langit","Terbang di atas awan","Layang-layang mengangkat Ton tinggi melepasi bumbung dan puncak pokok.","Padang di bawah kelihatan sekecil sapu tangan.","#3a7aa8"],["Pintu gerbang awan","Masuk ke kerajaan","Di atas awan tersergam pintu gerbang besar daripada kertas berwarna.","Layang-layang pengawal tunduk menyambut tetamu dari bumi.","#3a7aa8"],["Bandar pakpao","Lawati bandar pertama","Bandar pertama penuh dengan layang-layang pakpao yang kecil dan tangkas.","Mereka menari di atas hembusan bayu lembut yang terakhir.","#c0663a"],["Bandar naga","Minta pertolongan","Seterusnya bandar layang-layang naga yang panjang dan berwarna-warni.","Naga paling tua berkata angin telah putus di puncak Gunung Awan.","#c0663a"],["Bandar ikan","Kumpul barang untuk membaiki","Layang-layang ikan dari seluruh dunia memberi Ton seutas benang pelangi.","“Ikat semula angin dengan benang ini.”","#c0663a"],["Bandar burung","Cari kawan seperjalanan","Layang-layang helang yang besar menawarkan diri membawa Ton ke Gunung Awan.","Layang-layang bintang Ton terbang dengan bangga di sebelahnya.","#c0663a"],["Lautan awan","Seberangi lautan awan","Mereka terbang di atas lautan awan yang lembut seperti kapas.","Di hadapan, pelangi melengkung seperti jambatan.","#4f8a6a"],["Angin puting beliung yang nakal","Lepaskan diri dari puting beliung","Angin puting beliung yang nakal datang dan cuba menyimpulkan tali.","Ton berpusing bersamanya lalu terlepas.","#4f8a6a"],["Puncak Gunung Awan","Sampai ke destinasi","Di puncak terletak reben angin biru terang yang putus dua.","Kedua-dua hujungnya berkibar lemah.","#4f8a6a"],["Mengikat angin","Baiki angin","Dengan benang pelangi, Ton mengikat dua cebisan angin itu dengan teliti.","Simpulan terakhir terikat kemas.","#4f8a6a"],["Angin musim panas kembali","Bangunkan angin","Angin menarik nafas panjang dan bertiup ke seluruh langit.","Semua layang-layang di kerajaan terbang serentak.","#7a4fa0"],["Perarakan layang-layang","Sertai perarakan","Kerajaan mengadakan perarakan layang-layang yang paling panjang untuk berterima kasih kepada Ton.","Layang-layang dari semua bandar bersama-sama membentuk pelangi.","#7a4fa0"],["Melayang turun","Kembali ke bumi","Bayu yang hangat menurunkan Ton dengan lembut.","Kawan-kawannya bersorak apabila semua layang-layang terbang semula.","#7a4fa0"],["Layang-layang untuk semua","Kongsi langit","Ton mengajar kawan-kawannya membuat layang-layang sendiri, dan langit penuh warna.","Apa yang kita buat dengan tangan dan hati boleh membawa kita jauh. Tamat.","#7a4fa0"]],"fil":[["Ang parang sa tag-araw","Kilalanin si Ton at ang saranggola niya","Si Ton mismo ang gumawa ng pula-at-gintong saranggolang bituin at dinala niya ito sa malawak na parang.","Pero walang hangin ngayon, at bumabagsak ang lahat ng saranggola.","#3a7aa8"],["Ang saranggolang nagsasalita","Pakinggan ang saranggola","Biglang bumulong ang saranggola, “Nasira ang hangin ng tag-araw. Pakiusap, tulungan mo kami.”","“Hawakan mong mabuti ang pisi, at dadalhin ka namin doon.”","#3a7aa8"],["Sa langit","Lumipad lampas sa mga ulap","Itinaas ng saranggola si Ton nang mataas sa ibabaw ng mga bubong at tuktok ng puno.","Naging kasinliit ng panyo ang parang sa ibaba.","#3a7aa8"],["Ang tarangkahan ng ulap","Pumasok sa kaharian","Sa ibabaw ng mga ulap ay may malaking tarangkahang gawa sa makukulay na papel.","Yumuko ang mga bantay na saranggola para salubungin ang panauhin mula sa lupa.","#3a7aa8"],["Lungsod ng pakpao","Bisitahin ang unang lungsod","Puno ang unang lungsod ng maliliit at maliliksing saranggolang pakpao.","Sumasayaw sila sa mga huling mahinang simoy.","#c0663a"],["Lungsod ng dragon","Humingi ng tulong","Sunod ang lungsod ng mahahaba at makukulay na saranggolang dragon.","Sinabi ng pinakamatandang dragon na naputol ang hangin sa tuktok ng Bundok Ulap.","#c0663a"],["Lungsod ng isda","Mag-ipon ng pang-ayos","Binigyan si Ton ng mga saranggolang isda mula sa buong mundo ng sinulid na bahaghari.","“Itali mong muli ang hangin gamit ito.”","#c0663a"],["Lungsod ng ibon","Humanap ng kasama sa paglalakbay","Nag-alok ang isang malaking saranggolang agila na dalhin si Ton sa Bundok Ulap.","Buong pagmamalaking lumilipad sa tabi nila ang saranggolang bituin ni Ton.","#c0663a"],["Ang dagat ng ulap","Tawirin ang dagat ng ulap","Lumipad sila sa ibabaw ng dagat ng ulap na kasinlambot ng bulak.","Sa unahan, nakaarko ang bahaghari na parang tulay.","#4f8a6a"],["Ang pilyong ipuipo","Takasan ang ipuipo","Dumating ang isang pilyong ipuipo at sinubukang buhulin ang mga pisi.","Umikot si Ton kasabay nito at nakawala.","#4f8a6a"],["Tuktok ng Bundok Ulap","Marating ang pupuntahan","Sa tuktok ay may matingkad na asul na laso ng hangin na naputol sa gitna.","Mahinang pumapagaspas ang dalawang dulo nito.","#4f8a6a"],["Pagtali sa hangin","Ayusin ang hangin","Gamit ang sinulid na bahaghari, maingat na pinagtali ni Ton ang dalawang piraso ng hangin.","Mahigpit ang huling buhol.","#4f8a6a"],["Bumalik ang hangin ng tag-araw","Gisingin ang hangin","Huminga nang malalim ang hangin at umihip sa buong langit.","Sabay-sabay na lumipad ang lahat ng saranggola sa kaharian.","#7a4fa0"],["Parada ng saranggola","Sumali sa parada","Nagdaos ang kaharian ng pinakamahabang parada ng saranggola para pasalamatan si Ton.","Bumuo ng bahaghari ang mga saranggola mula sa lahat ng lungsod.","#7a4fa0"],["Pababa","Bumalik sa lupa","Dahan-dahang ibinaba si Ton ng mainit na simoy.","Nagsigawan sa tuwa ang mga kaibigan niya nang muling lumipad ang lahat ng saranggola.","#7a4fa0"],["Saranggola para sa lahat","Ibahagi ang langit","Tinuruan ni Ton ang mga kaibigan na gumawa ng sariling saranggola, at napuno ng kulay ang langit.","Ang ginagawa natin gamit ang kamay at puso ay kayang magdala sa atin sa malayo. Wakas.","#7a4fa0"]],"hi":[["गर्मियों का मैदान","टोन और उसकी पतंग से मिलो","टोन ने ख़ुद लाल-सुनहरी तारे वाली पतंग बनाई है और उसे बड़े मैदान में लाया है।","पर आज हवा नहीं है, और सारी पतंगें गिर रही हैं।","#3a7aa8"],["बोलने वाली पतंग","पतंग की बात सुनो","अचानक पतंग फुसफुसाती है, “गर्मियों की हवा टूट गई है। हमारी मदद करो।”","“डोर कसकर पकड़ो, हम तुम्हें वहाँ ले चलेंगे।”","#3a7aa8"],["आसमान में","बादलों के ऊपर उड़ो","पतंग टोन को छतों और पेड़ों की चोटियों से बहुत ऊपर ले जाती है।","नीचे का मैदान रूमाल जितना छोटा हो जाता है।","#3a7aa8"],["बादलों का द्वार","राज्य में प्रवेश करो","बादलों के ऊपर रंगीन काग़ज़ का एक बड़ा द्वार खड़ा है।","पहरेदार पतंगें झुककर धरती से आए मेहमान का स्वागत करती हैं।","#3a7aa8"],["पाकपाओ का शहर","पहले शहर में जाओ","पहला शहर छोटी, फुर्तीली पाकपाओ पतंगों से भरा है।","वे आख़िरी हल्की हवाओं पर नाचती हैं।","#c0663a"],["ड्रैगन का शहर","मदद माँगो","फिर आता है लंबी, रंग-बिरंगी ड्रैगन पतंगों का शहर।","सबसे बूढ़ा ड्रैगन बताता है कि बादल पहाड़ की चोटी पर हवा टूट गई है।","#c0663a"],["मछलियों का शहर","मरम्मत का सामान जुटाओ","दुनिया भर की मछली पतंगें टोन को इंद्रधनुषी धागा देती हैं।","“इससे हवा को फिर से बाँध दो।”","#c0663a"],["पक्षियों का शहर","सफ़र का साथी खोजो","एक बड़ी चील पतंग टोन को बादल पहाड़ तक ले जाने की पेशकश करती है।","टोन की तारे वाली पतंग गर्व से साथ-साथ उड़ती है।","#c0663a"],["बादलों का समुद्र","बादलों का समुद्र पार करो","वे रुई जैसे नरम बादलों के समुद्र के ऊपर उड़ते हैं।","आगे एक इंद्रधनुष पुल की तरह झुका है।","#4f8a6a"],["शरारती बवंडर","बवंडर से बचो","एक शरारती बवंडर घूमता हुआ आता है और डोरियाँ उलझाने की कोशिश करता है।","टोन उसके साथ घूमकर छूट निकलता है।","#4f8a6a"],["बादल पहाड़ की चोटी","मंज़िल तक पहुँचो","चोटी पर हवा का एक चमकीला नीला रिबन दो टुकड़ों में टूटा पड़ा है।","दोनों सिरे धीरे-धीरे फड़फड़ा रहे हैं।","#4f8a6a"],["हवा को बाँधना","हवा ठीक करो","इंद्रधनुषी धागे से टोन हवा के दोनों टुकड़ों को ध्यान से बाँधता है।","आख़िरी गाँठ मज़बूती से बँध जाती है।","#4f8a6a"],["गर्मियों की हवा लौटी","हवा को जगाओ","हवा गहरी साँस लेती है और पूरे आसमान में बहने लगती है।","राज्य की सारी पतंगें एक साथ उड़ जाती हैं।","#7a4fa0"],["पतंगों की परेड","परेड में शामिल हो","टोन को धन्यवाद देने के लिए राज्य अपनी सबसे लंबी पतंग परेड निकालता है।","सभी शहरों की पतंगें मिलकर इंद्रधनुष बनाती हैं।","#7a4fa0"],["धीरे-धीरे नीचे","धरती पर लौटो","एक गरम हवा टोन को धीरे से नीचे उतार देती है।","सारी पतंगें फिर उड़ती देख उसके दोस्त ख़ुशी से चिल्लाते हैं।","#7a4fa0"],["सबके लिए पतंग","आसमान बाँटो","टोन अपने दोस्तों को अपनी पतंग बनाना सिखाता है, और आसमान रंगों से भर जाता है।","जो हम अपने हाथों और दिल से बनाते हैं, वह हमें दूर तक ले जा सकता है। समाप्त।","#7a4fa0"]],"ar":[["مرج الصيف","تعرّف على تون وطائرته الورقية","صنع تون بنفسه طائرة ورقية على شكل نجمة حمراء وذهبية، وحملها إلى المرج الكبير.","لكن لا ريح اليوم، وكل الطائرات الورقية تسقط.","#3a7aa8"],["الطائرة الورقية المتكلّمة","استمع إلى الطائرة الورقية","فجأة تهمس الطائرة الورقية: «ريح الصيف انكسرت. ساعدنا من فضلك».","«أمسك الخيط جيدًا، وسنأخذك إلى هناك».","#3a7aa8"],["إلى السماء","طِر فوق الغيوم","ترفع الطائرة الورقية تون عاليًا فوق الأسطح وقمم الأشجار.","يصير المرج في الأسفل صغيرًا كمنديل.","#3a7aa8"],["بوابة الغيوم","ادخل المملكة","فوق الغيوم تقف بوابة كبيرة من الورق الملوّن.","تنحني الطائرات الورقية الحارسة ترحيبًا بالضيف القادم من الأرض.","#3a7aa8"],["مدينة باكباو","زُر المدينة الأولى","المدينة الأولى مليئة بطائرات باكباو الصغيرة الرشيقة.","ترقص على آخر النسمات اللطيفة.","#c0663a"],["مدينة التنانين","اطلب المساعدة","بعدها تأتي مدينة طائرات التنين الطويلة الملوّنة.","يقول أكبر التنانين إن الريح انقطعت على قمة جبل الغيوم.","#c0663a"],["مدينة الأسماك","اجمع أدوات الإصلاح","تعطي طائرات السمك من كل أنحاء العالم تون خيطًا بألوان قوس قزح.","«اربط به الريح من جديد».","#c0663a"],["مدينة الطيور","ابحث عن رفيق رحلة","يعرض طائر ورقي كبير على شكل نسر أن يحمل تون إلى جبل الغيوم.","تطير نجمة تون الورقية بفخر إلى جانبهما.","#c0663a"],["بحر الغيوم","اعبر بحر الغيوم","يطيرون فوق بحر من الغيوم الناعمة كالقطن.","في الأمام، ينحني قوس قزح مثل جسر.","#4f8a6a"],["الإعصار المشاغب","اهرب من الإعصار","يأتي إعصار صغير مشاغب ويحاول أن يشبك الخيوط ببعضها.","يدور تون معه حتى يفلت منه.","#4f8a6a"],["قمة جبل الغيوم","اصل إلى الهدف","على القمة يرقد شريط ريح أزرق لامع مقطوع نصفين.","طرفاه يرفرفان بضعف.","#4f8a6a"],["ربط الريح","أصلح الريح","بخيط قوس قزح، يربط تون قطعتي الريح بعناية.","العقدة الأخيرة متينة.","#4f8a6a"],["ريح الصيف تعود","أيقظ الريح","تأخذ الريح نفسًا عميقًا وتهبّ في السماء كلها.","تطير كل الطائرات الورقية في المملكة معًا.","#7a4fa0"],["موكب الطائرات الورقية","انضم إلى الموكب","تقيم المملكة أطول موكب للطائرات الورقية لتشكر تون.","تشكّل الطائرات الورقية من كل المدن معًا قوس قزح.","#7a4fa0"],["الهبوط برفق","عُد إلى الأرض","ينزل نسيم دافئ تون برفق إلى الأسفل.","يهتف أصدقاؤه فرحًا حين تطير كل الطائرات الورقية من جديد.","#7a4fa0"],["طائرات ورقية للجميع","تقاسم السماء","يعلّم تون أصدقاءه صنع طائراتهم الورقية، فتمتلئ السماء بالألوان.","ما نصنعه بأيدينا وقلوبنا يمكن أن يحملنا بعيدًا. النهاية.","#7a4fa0"]],"fr":[["Le grand champ d’été","Rencontre Ton et son cerf-volant","Ton a fabriqué tout seul un cerf-volant étoile rouge et or, et il l’emporte au grand champ.","Mais aujourd’hui il n’y a pas de vent, et tous les cerfs-volants tombent.","#3a7aa8"],["Le cerf-volant qui parle","Écoute le cerf-volant","Soudain, le cerf-volant chuchote : « Le vent d’été est cassé. Aide-nous, s’il te plaît. »","« Tiens bien la ficelle, et nous t’emmènerons là-bas. »","#3a7aa8"],["Dans le ciel","Vole au-dessus des nuages","Le cerf-volant soulève Ton bien au-dessus des toits et des arbres.","En bas, le champ devient aussi petit qu’un mouchoir.","#3a7aa8"],["La porte des nuages","Entre dans le royaume","Au-dessus des nuages se dresse une grande porte en papier de toutes les couleurs.","Les cerfs-volants gardiens s’inclinent pour accueillir l’invité de la terre.","#3a7aa8"],["La ville des pakpaos","Visite la première ville","La première ville est pleine de petits cerfs-volants pakpao très rapides.","Ils dansent sur les dernières brises légères.","#c0663a"],["La ville des dragons","Demande de l’aide","Ensuite vient une ville de longs cerfs-volants dragons colorés.","Le plus vieux dragon dit que le vent s’est cassé au sommet de la Montagne des Nuages.","#c0663a"],["La ville des poissons","Rassemble de quoi réparer","Des cerfs-volants en forme de poisson venus du monde entier donnent à Ton un fil arc-en-ciel.","« Avec ce fil, renoue le vent. »","#c0663a"],["La ville des oiseaux","Trouve un compagnon de route","Un grand cerf-volant aigle propose d’emmener Ton jusqu’à la Montagne des Nuages.","Le cerf-volant étoile de Ton vole fièrement à côté d’eux.","#c0663a"],["La mer de nuages","Traverse la mer de nuages","Ils volent au-dessus d’une mer de nuages douce comme du coton.","Un arc-en-ciel se courbe devant eux comme un pont.","#4f8a6a"],["Le tourbillon farceur","Échappe au tourbillon","Un tourbillon farceur arrive et essaie d’emmêler les ficelles.","Ton tourne avec lui et se libère.","#4f8a6a"],["Le sommet de la montagne","Atteins le but","Au sommet de la Montagne des Nuages, un ruban de vent bleu clair est cassé en deux.","Les deux bouts flottent tout faiblement.","#4f8a6a"],["Nouer le vent","Répare le vent","Avec le fil arc-en-ciel, Ton noue soigneusement les deux morceaux de vent.","Le dernier nœud est bien serré et solide.","#4f8a6a"],["Le vent d’été revient","Réveille le vent","Le vent prend une grande inspiration et souffle dans tout le ciel.","Tous les cerfs-volants du royaume s’envolent en même temps.","#7a4fa0"],["La parade des cerfs-volants","Rejoins la parade","Le royaume organise sa plus longue parade pour remercier Ton.","Des cerfs-volants de toutes les villes s’alignent comme un arc-en-ciel.","#7a4fa0"],["Le retour en planant","Redescends sur terre","Une brise tiède ramène Ton doucement au sol.","Ses amis applaudissent en voyant tous leurs cerfs-volants voler à nouveau.","#7a4fa0"],["Des cerfs-volants pour tous","Partage le ciel","Ton apprend à ses amis à fabriquer leurs cerfs-volants, et le ciel se remplit de couleurs.","Ce que l’on fait avec ses mains et son cœur peut nous emmener loin. Fin.","#7a4fa0"]],"de":[["Die Sommerwiese","Lerne Ton und seinen Drachen kennen","Ton hat ganz allein einen rot-goldenen Sterndrachen gebaut und bringt ihn zur großen Wiese.","Aber heute gibt es keinen Wind, und alle Drachen fallen herunter.","#3a7aa8"],["Der sprechende Drachen","Hör dem Drachen zu","Plötzlich flüstert der Drachen: „Der Sommerwind ist kaputt. Bitte hilf uns.“","„Halt die Schnur gut fest, dann bringen wir dich hin.“","#3a7aa8"],["Hinauf in den Himmel","Flieg über die Wolken","Der Drachen hebt Ton hoch über Dächer und Baumkronen.","Die Wiese unten wird so klein wie ein Taschentuch.","#3a7aa8"],["Das Wolkentor","Betritt das Königreich","Über den Wolken steht ein großes Tor aus buntem Papier.","Die Wächterdrachen verneigen sich vor dem Gast von der Erde.","#3a7aa8"],["Die Pakpao-Stadt","Besuche die erste Stadt","Die erste Stadt ist voller kleiner, flinker Pakpao-Drachen.","Sie tanzen auf den letzten sanften Lüftchen.","#c0663a"],["Die Drachenschlangen-Stadt","Bitte um Hilfe","Dann kommt eine Stadt voller langer, bunter Schlangendrachen.","Der älteste sagt, der Wind sei auf dem Gipfel des Wolkenbergs gerissen.","#c0663a"],["Die Fischdrachen-Stadt","Sammle Werkzeug zum Flicken","Fischdrachen aus aller Welt schenken Ton einen Regenbogenfaden.","„Damit knotest du den Wind wieder zusammen.“","#c0663a"],["Die Vogeldrachen-Stadt","Finde einen Reisegefährten","Ein großer Adlerdrachen bietet an, Ton zum Wolkenberg zu fliegen.","Tons Sterndrachen fliegt stolz neben ihnen.","#c0663a"],["Das Wolkenmeer","Überquere das Wolkenmeer","Sie fliegen über ein Wolkenmeer, weich wie Watte.","Vor ihnen spannt sich ein Regenbogen wie eine Brücke.","#4f8a6a"],["Der freche Wirbelwind","Entkomme dem Wirbelwind","Ein frecher Wirbelwind saust heran und will die Schnüre verheddern.","Ton dreht sich mit ihm und kommt frei.","#4f8a6a"],["Der Gipfel des Wolkenbergs","Erreiche das Ziel","Auf dem Gipfel liegt ein klares, blaues Windband, in zwei Teile gerissen.","Beide Enden flattern ganz schwach.","#4f8a6a"],["Den Wind verknoten","Flicke den Wind","Mit dem Regenbogenfaden knotet Ton die beiden Windstücke sorgfältig zusammen.","Der letzte Knoten hält fest und stark.","#4f8a6a"],["Der Sommerwind ist zurück","Weck den Wind","Der Wind holt tief Luft und weht über den ganzen Himmel.","Alle Drachen im Königreich steigen auf einmal auf.","#7a4fa0"],["Die Drachenparade","Mach bei der Parade mit","Das Königreich feiert seine längste Drachenparade, um Ton zu danken.","Drachen aus allen Städten reihen sich auf wie ein Regenbogen.","#7a4fa0"],["Zurück nach Hause gleiten","Kehr auf die Erde zurück","Eine warme Brise trägt Ton sanft hinunter.","Seine Freunde jubeln, als alle ihre Drachen wieder fliegen.","#7a4fa0"],["Drachen für alle","Teilt euch den Himmel","Ton zeigt seinen Freunden, wie man Drachen baut, und der Himmel wird bunt.","Was wir mit Händen und Herz machen, kann uns weit tragen. Ende.","#7a4fa0"]],"it":[["Il prato d’estate","Conosci Ton e il suo aquilone","Ton ha costruito da solo un aquilone a stella rosso e oro e lo porta al grande prato.","Ma oggi non c’è vento e tutti gli aquiloni cadono.","#3a7aa8"],["L’aquilone che parla","Ascolta l’aquilone","All’improvviso l’aquilone sussurra: «Il vento d’estate si è rotto. Aiutaci, per favore».","«Tieni forte il filo e ti porteremo lassù.»","#3a7aa8"],["Su nel cielo","Vola sopra le nuvole","L’aquilone solleva Ton in alto sopra i tetti e gli alberi.","Il prato laggiù diventa piccolo come un fazzoletto.","#3a7aa8"],["La porta delle nuvole","Entra nel regno","Sopra le nuvole c’è una grande porta di carta colorata.","Gli aquiloni guardiani si inchinano per accogliere l’ospite dalla terra.","#3a7aa8"],["La città dei pakpao","Visita la prima città","La prima città è piena di piccoli aquiloni pakpao, velocissimi.","Danzano sulle ultime brezze leggere.","#c0663a"],["La città dei draghi","Chiedi aiuto","Poi arriva una città di lunghi aquiloni a drago colorati.","Il drago più anziano dice che il vento si è rotto in cima al Monte delle Nuvole.","#c0663a"],["La città dei pesci","Raccogli ciò che serve","Aquiloni a forma di pesce da tutto il mondo danno a Ton un filo arcobaleno.","«Usa questo filo per riannodare il vento.»","#c0663a"],["La città degli uccelli","Trova un compagno di viaggio","Un grande aquilone aquila si offre di portare Ton al Monte delle Nuvole.","L’aquilone a stella di Ton vola fiero accanto a loro.","#c0663a"],["Il mare di nuvole","Attraversa il mare di nuvole","Volano sopra un mare di nuvole morbido come il cotone.","Davanti a loro un arcobaleno si piega come un ponte.","#4f8a6a"],["Il turbine dispettoso","Supera il turbine","Un turbine dispettoso arriva e prova ad aggrovigliare i fili.","Ton gira insieme a lui e si libera.","#4f8a6a"],["La cima del monte","Raggiungi la meta","In cima al Monte delle Nuvole c’è un nastro di vento azzurro, spezzato in due.","Le due estremità sventolano debolmente.","#4f8a6a"],["Annodare il vento","Ripara il vento","Con il filo arcobaleno Ton annoda con cura i due pezzi di vento.","L’ultimo nodo è stretto e robusto.","#4f8a6a"],["Torna il vento d’estate","Risveglia il vento","Il vento fa un grande respiro e soffia per tutto il cielo.","Tutti gli aquiloni del regno si alzano insieme.","#7a4fa0"],["La parata degli aquiloni","Unisciti alla parata","Il regno organizza la sua parata più lunga per ringraziare Ton.","Aquiloni di tutte le città si mettono in fila come un arcobaleno.","#7a4fa0"],["Planando verso casa","Torna a terra","Una brezza tiepida riporta Ton giù dolcemente.","I suoi amici esultano vedendo volare di nuovo tutti gli aquiloni.","#7a4fa0"],["Aquiloni per tutti","Condividi il cielo","Ton insegna agli amici a costruire aquiloni e il cielo si riempie di colori.","Ciò che creiamo con le mani e con il cuore può portarci lontano. Fine.","#7a4fa0"]],"pt":[["O campo de verão","Conheça Ton e sua pipa","Ton fez sozinho uma pipa de estrela vermelha e dourada e a leva ao grande campo.","Mas hoje não tem vento, e todas as pipas caem.","#3a7aa8"],["A pipa que fala","Escute a pipa","De repente, a pipa sussurra: “O vento do verão se partiu. Ajude a gente, por favor.”","“Segure bem a linha e nós levamos você até lá.”","#3a7aa8"],["Rumo ao céu","Voe acima das nuvens","A pipa ergue Ton bem acima dos telhados e das árvores.","O campo lá embaixo fica do tamanho de um lencinho.","#3a7aa8"],["O portão das nuvens","Entre no reino","Acima das nuvens há um grande portão de papel colorido.","As pipas guardiãs se curvam para receber o visitante da terra.","#3a7aa8"],["A cidade das pakpao","Visite a primeira cidade","A primeira cidade é cheia de pipas pakpao pequenas e ligeiras.","Elas dançam nas últimas brisas suaves.","#c0663a"],["A cidade dos dragões","Peça ajuda","Depois vem uma cidade de pipas-dragão compridas e coloridas.","O dragão mais velho diz que o vento se partiu no topo da Montanha das Nuvens.","#c0663a"],["A cidade dos peixes","Junte o que precisa","Pipas em forma de peixe do mundo todo dão a Ton uma linha de arco-íris.","“Use esta linha para amarrar o vento de novo.”","#c0663a"],["A cidade dos pássaros","Ache um companheiro de viagem","Uma grande pipa-águia oferece levar Ton à Montanha das Nuvens.","A pipa-estrela de Ton voa orgulhosa ao lado deles.","#c0663a"],["O mar de nuvens","Atravesse o mar de nuvens","Eles voam sobre um mar de nuvens macio como algodão.","Um arco-íris se curva à frente como uma ponte.","#4f8a6a"],["O redemoinho travesso","Escape do redemoinho","Um redemoinho travesso chega e tenta enroscar as linhas.","Ton gira junto com ele e se solta.","#4f8a6a"],["O topo da montanha","Chegue ao destino","No topo da Montanha das Nuvens, uma fita de vento azul-clara está partida em duas.","As duas pontas tremulam fraquinhas.","#4f8a6a"],["Amarrando o vento","Conserte o vento","Com a linha de arco-íris, Ton amarra com cuidado os dois pedaços de vento.","O último nó fica firme e forte.","#4f8a6a"],["O vento do verão volta","Desperte o vento","O vento respira fundo e sopra pelo céu inteiro.","Todas as pipas do reino sobem de uma vez.","#7a4fa0"],["O desfile das pipas","Entre no desfile","O reino faz seu desfile mais longo para agradecer a Ton.","Pipas de todas as cidades se alinham como um arco-íris.","#7a4fa0"],["Planando de volta","Volte para a terra","Uma brisa morna leva Ton de volta ao chão bem devagar.","Os amigos comemoram ao ver todas as pipas voando outra vez.","#7a4fa0"],["Pipas para todos","Divida o céu","Ton ensina os amigos a fazer suas próprias pipas, e o céu se enche de cores.","O que fazemos com as mãos e o coração pode nos levar longe. Fim.","#7a4fa0"]],"ru":[["Летнее поле","Познакомься с Тоном и его змеем","Тон сам сделал красно-золотого змея-звезду и несёт его на большое поле.","Но сегодня нет ветра, и все змеи падают.","#3a7aa8"],["Говорящий змей","Послушай змея","Вдруг змей шепчет: «Летний ветер сломался. Помоги нам, пожалуйста».","«Держи нитку крепко, и мы тебя туда отнесём».","#3a7aa8"],["В небо","Взлети над облаками","Змей поднимает Тона высоко над крышами и верхушками деревьев.","Поле внизу становится маленьким, как платочек.","#3a7aa8"],["Облачные ворота","Войди в королевство","Над облаками стоят большие ворота из цветной бумаги.","Змеи-стражи кланяются, встречая гостя с земли.","#3a7aa8"],["Город пакпао","Посети первый город","Первый город полон маленьких быстрых змеев пакпао.","Они танцуют на последних лёгких дуновениях.","#c0663a"],["Город драконов","Попроси о помощи","Потом идёт город длинных разноцветных змеев-драконов.","Старейший дракон говорит, что ветер оборвался на вершине Облачной горы.","#c0663a"],["Город рыб","Собери всё для починки","Змеи-рыбы со всего света дарят Тону радужную нить.","«Свяжи ею ветер снова».","#c0663a"],["Город птиц","Найди попутчика","Большой змей-орёл предлагает отвезти Тона на Облачную гору.","Звёздный змей Тона гордо летит рядом.","#c0663a"],["Море облаков","Перелети облачное море","Они летят над морем облаков, мягких, как вата.","Впереди радуга изгибается, как мост.","#4f8a6a"],["Озорной вихрь","Ускользни от вихря","Озорной вихрь налетает и пытается спутать нитки.","Тон кружится вместе с ним и вырывается.","#4f8a6a"],["Вершина Облачной горы","Достигни цели","На вершине лежит ярко-голубая лента ветра, разорванная пополам.","Оба конца слабо трепещут.","#4f8a6a"],["Связать ветер","Почини ветер","Радужной нитью Тон аккуратно связывает два куска ветра.","Последний узел держится крепко.","#4f8a6a"],["Летний ветер вернулся","Разбуди ветер","Ветер глубоко вздыхает и дует по всему небу.","Все змеи королевства взлетают разом.","#7a4fa0"],["Парад змеев","Присоединись к параду","Королевство устраивает свой самый длинный парад змеев, чтобы поблагодарить Тона.","Змеи из всех городов вместе складываются в радугу.","#7a4fa0"],["Обратно вниз","Вернись на землю","Тёплый ветерок мягко опускает Тона вниз.","Друзья радуются, когда все змеи снова летают.","#7a4fa0"],["Змеи для всех","Поделись небом","Тон учит друзей делать своих змеев, и небо наполняется красками.","То, что мы делаем руками и сердцем, может унести нас далеко. Конец.","#7a4fa0"]],"tr":[["Yaz çayırı","Ton ve uçurtmasıyla tanış","Ton kırmızı-altın yıldız uçurtmasını kendi yapmış ve onu büyük çayıra getirmiştir.","Ama bugün hiç rüzgâr yok ve bütün uçurtmalar düşüyor.","#3a7aa8"],["Konuşan uçurtma","Uçurtmayı dinle","Birden uçurtma fısıldar: “Yaz rüzgârı bozuldu. Lütfen bize yardım et.”","“İpi sıkı tut, seni oraya götürelim.”","#3a7aa8"],["Gökyüzüne","Bulutların üstüne uç","Uçurtma Ton’u damların ve ağaç tepelerinin çok üstüne kaldırır.","Aşağıdaki çayır bir mendil kadar küçülür.","#3a7aa8"],["Bulut kapısı","Krallığa gir","Bulutların üstünde renkli kâğıttan büyük bir kapı durur.","Muhafız uçurtmalar yeryüzünden gelen konuğu eğilerek karşılar.","#3a7aa8"],["Pakpao kenti","İlk kenti ziyaret et","İlk kent küçük, çevik pakpao uçurtmalarıyla doludur.","Son hafif esintilerin üzerinde dans ederler.","#c0663a"],["Ejderha kenti","Yardım iste","Sonra uzun, rengârenk ejderha uçurtmaların kenti gelir.","En yaşlı ejderha, rüzgârın Bulut Dağı’nın tepesinde koptuğunu söyler.","#c0663a"],["Balık kenti","Onarım malzemelerini topla","Dünyanın dört bir yanından balık uçurtmalar Ton’a gökkuşağı renginde bir ip verir.","“Rüzgârı bununla yeniden bağla.”","#c0663a"],["Kuş kenti","Bir yol arkadaşı bul","Büyük bir kartal uçurtma, Ton’u Bulut Dağı’na götürmeyi teklif eder.","Ton’un yıldız uçurtması gururla yanlarında uçar.","#c0663a"],["Bulut denizi","Bulut denizini geç","Pamuk gibi yumuşak bir bulut denizinin üstünden uçarlar.","İleride bir gökkuşağı köprü gibi kıvrılır.","#4f8a6a"],["Yaramaz hortum","Hortumdan kurtul","Yaramaz bir hortum fırıl fırıl gelir ve ipleri dolaştırmaya çalışır.","Ton onunla birlikte döner ve kurtulur.","#4f8a6a"],["Bulut Dağı’nın tepesi","Hedefe ulaş","Tepede ikiye kopmuş, parlak mavi bir rüzgâr kurdelesi yatar.","İki ucu da zayıfça dalgalanır.","#4f8a6a"],["Rüzgârı bağlamak","Rüzgârı onar","Ton gökkuşağı ipiyle rüzgârın iki parçasını özenle birbirine bağlar.","Son düğüm sımsıkı tutar.","#4f8a6a"],["Yaz rüzgârı geri döndü","Rüzgârı uyandır","Rüzgâr derin bir nefes alır ve bütün gökyüzünde eser.","Krallıktaki tüm uçurtmalar aynı anda havalanır.","#7a4fa0"],["Uçurtma geçidi","Geçide katıl","Krallık, Ton’a teşekkür etmek için en uzun uçurtma geçidini düzenler.","Bütün kentlerden uçurtmalar birlikte bir gökkuşağı oluşturur.","#7a4fa0"],["Aşağı süzülüş","Yeryüzüne dön","Ilık bir meltem Ton’u yavaşça aşağı indirir.","Bütün uçurtmalar yeniden uçarken arkadaşları sevinçle bağırır.","#7a4fa0"],["Herkese uçurtma","Gökyüzünü paylaş","Ton arkadaşlarına kendi uçurtmalarını yapmayı öğretir ve gökyüzü renklerle dolar.","Ellerimizle ve kalbimizle yaptıklarımız bizi çok uzaklara taşıyabilir. Son.","#7a4fa0"]],"pl":[["Letnia łąka","Poznaj Tona i jego latawiec","Ton sam zrobił czerwono-złoty latawiec w kształcie gwiazdy i niesie go na wielką łąkę.","Ale dziś nie ma wiatru i wszystkie latawce spadają.","#3a7aa8"],["Mówiący latawiec","Posłuchaj latawca","Nagle latawiec szepcze: „Letni wiatr się zepsuł. Pomóż nam, proszę.”","„Trzymaj mocno sznurek, a zabierzemy cię tam.”","#3a7aa8"],["W niebo","Wzleć ponad chmury","Latawiec unosi Tona wysoko nad dachy i czubki drzew.","Łąka w dole robi się mała jak chusteczka.","#3a7aa8"],["Brama w chmurach","Wejdź do królestwa","Nad chmurami stoi wielka brama z kolorowego papieru.","Latawce-strażnicy kłaniają się, witając gościa z ziemi.","#3a7aa8"],["Miasto pakpao","Odwiedź pierwsze miasto","Pierwsze miasto pełne jest małych, zwinnych latawców pakpao.","Tańczą na ostatnich łagodnych powiewach.","#c0663a"],["Miasto smoków","Poproś o pomoc","Potem przychodzi miasto długich, kolorowych latawców-smoków.","Najstarszy smok mówi, że wiatr zerwał się na szczycie Góry Chmur.","#c0663a"],["Miasto ryb","Zbierz rzeczy do naprawy","Latawce-ryby z całego świata dają Tonowi tęczową nić.","„Zwiąż nią wiatr z powrotem.”","#c0663a"],["Miasto ptaków","Znajdź towarzysza podróży","Wielki latawiec-orzeł proponuje, że zawiezie Tona na Górę Chmur.","Gwiaździsty latawiec Tona leci dumnie obok nich.","#c0663a"],["Morze chmur","Przeleć nad morzem chmur","Lecą nad morzem chmur miękkich jak wata.","Przed nimi tęcza wygina się jak most.","#4f8a6a"],["Psotna trąba powietrzna","Ucieknij przed trąbą","Psotna trąba powietrzna nadlatuje i próbuje splątać sznurki.","Ton kręci się razem z nią i się wyswobadza.","#4f8a6a"],["Szczyt Góry Chmur","Dotrzyj do celu","Na szczycie leży jasnoniebieska wstęga wiatru przerwana na pół.","Oba końce słabo trzepoczą.","#4f8a6a"],["Wiązanie wiatru","Napraw wiatr","Tęczową nicią Ton starannie wiąże oba kawałki wiatru.","Ostatni węzeł trzyma mocno.","#4f8a6a"],["Letni wiatr wraca","Obudź wiatr","Wiatr bierze głęboki oddech i wieje po całym niebie.","Wszystkie latawce w królestwie wzlatują naraz.","#7a4fa0"],["Parada latawców","Dołącz do parady","Królestwo urządza swoją najdłuższą paradę latawców, żeby podziękować Tonowi.","Latawce ze wszystkich miast tworzą razem tęczę.","#7a4fa0"],["Powrót w dół","Wróć na ziemię","Ciepła bryza łagodnie sprowadza Tona na dół.","Jego przyjaciele wiwatują, gdy wszystkie latawce znów latają.","#7a4fa0"],["Latawce dla wszystkich","Podziel się niebem","Ton uczy przyjaciół robić własne latawce i niebo wypełnia się kolorami.","To, co robimy rękami i sercem, może zanieść nas daleko. Koniec.","#7a4fa0"]],"nl":[["Het zomerveld","Maak kennis met Ton en zijn vlieger","Ton heeft helemaal zelf een rood-gouden stervlieger gemaakt en neemt hem mee naar het grote veld.","Maar vandaag is er geen wind, en alle vliegers vallen.","#3a7aa8"],["De pratende vlieger","Luister naar de vlieger","Ineens fluistert de vlieger: “De zomerwind is kapot. Help ons alsjeblieft.”","“Houd het touw goed vast, dan brengen we je erheen.”","#3a7aa8"],["De lucht in","Vlieg boven de wolken","De vlieger tilt Ton hoog boven de daken en boomtoppen.","Het veld beneden wordt zo klein als een zakdoek.","#3a7aa8"],["De wolkenpoort","Ga het rijk binnen","Boven de wolken staat een grote poort van gekleurd papier.","De wachtvliegers buigen om de gast van de aarde te verwelkomen.","#3a7aa8"],["De pakpaostad","Bezoek de eerste stad","De eerste stad zit vol kleine, snelle pakpaovliegers.","Ze dansen op de laatste zachte briesjes.","#c0663a"],["De drakenstad","Vraag om hulp","Daarna komt een stad vol lange, kleurige drakenvliegers.","De oudste draak zegt dat de wind op de top van de Wolkenberg is geknapt.","#c0663a"],["De vissenstad","Verzamel spullen om te repareren","Visvliegers uit de hele wereld geven Ton een regenboogdraad.","“Knoop daarmee de wind weer aan elkaar.”","#c0663a"],["De vogelstad","Vind een reisgenoot","Een grote adelaarsvlieger biedt aan Ton naar de Wolkenberg te vliegen.","Tons stervlieger vliegt trots naast hen.","#c0663a"],["De wolkenzee","Steek de wolkenzee over","Ze vliegen over een zee van wolken, zo zacht als watten.","Voor hen buigt een regenboog als een brug.","#4f8a6a"],["De ondeugende wervelwind","Ontsnap aan de wervelwind","Een ondeugende wervelwind raast aan en probeert de touwen in de knoop te leggen.","Ton draait met hem mee en komt los.","#4f8a6a"],["De top van de Wolkenberg","Bereik het doel","Op de top ligt een helderblauw lint van wind, in tweeën geknapt.","Beide uiteinden fladderen zwakjes.","#4f8a6a"],["De wind knopen","Repareer de wind","Met de regenboogdraad knoopt Ton de twee stukken wind zorgvuldig aan elkaar.","De laatste knoop zit stevig vast.","#4f8a6a"],["De zomerwind is terug","Maak de wind wakker","De wind haalt diep adem en waait over de hele lucht.","Alle vliegers in het rijk stijgen tegelijk op.","#7a4fa0"],["De vliegeroptocht","Doe mee met de optocht","Het rijk houdt zijn langste vliegeroptocht om Ton te bedanken.","Vliegers uit alle steden vormen samen een regenboog.","#7a4fa0"],["Terugzweven","Ga terug naar de aarde","Een warme bries brengt Ton zachtjes naar beneden.","Zijn vrienden juichen als alle vliegers weer vliegen.","#7a4fa0"],["Vliegers voor iedereen","Deel de lucht","Ton leert zijn vrienden zelf vliegers maken, en de lucht kleurt vrolijk.","Wat we met onze handen en ons hart maken, kan ons ver brengen. Einde.","#7a4fa0"]],"uk":[["Літнє поле","Познайомся з Тоном і його змієм","Тон сам зробив червоно-золотого змія-зірку і несе його на велике поле.","Але сьогодні немає вітру, і всі змії падають.","#3a7aa8"],["Змій, що розмовляє","Послухай змія","Раптом змій шепоче: «Літній вітер зламався. Допоможи нам, будь ласка».","«Тримай нитку міцно, і ми тебе туди донесемо».","#3a7aa8"],["У небо","Злети понад хмари","Змій піднімає Тона високо над дахами й верхівками дерев.","Поле внизу стає маленьким, як хусточка.","#3a7aa8"],["Хмарна брама","Увійди в королівство","Над хмарами стоїть велика брама з кольорового паперу.","Змії-вартові вклоняються, вітаючи гостя з землі.","#3a7aa8"],["Місто пакпао","Відвідай перше місто","Перше місто повне маленьких спритних зміїв пакпао.","Вони танцюють на останніх лагідних подихах вітру.","#c0663a"],["Місто драконів","Попроси допомоги","Далі місто довгих барвистих зміїв-драконів.","Найстарший дракон каже, що вітер урвався на вершині Хмарної гори.","#c0663a"],["Місто риб","Збери все для лагодження","Змії-риби з усього світу дарують Тонові райдужну нитку.","«Зв’яжи нею вітер знову».","#c0663a"],["Місто птахів","Знайди супутника","Великий змій-орел пропонує віднести Тона на Хмарну гору.","Зірковий змій Тона гордо летить поруч.","#c0663a"],["Море хмар","Перелети хмарне море","Вони летять над морем хмар, м’яких, як вата.","Попереду веселка вигинається, як міст.","#4f8a6a"],["Пустотливий вихор","Втечи від вихору","Пустотливий вихор налітає і намагається заплутати нитки.","Тон кружляє разом із ним і вивільняється.","#4f8a6a"],["Вершина Хмарної гори","Досягни мети","На вершині лежить яскраво-блакитна стрічка вітру, розірвана навпіл.","Обидва кінці ледь тріпочуть.","#4f8a6a"],["Зв’язати вітер","Полагодь вітер","Райдужною ниткою Тон дбайливо зв’язує два шматки вітру.","Останній вузол тримається міцно.","#4f8a6a"],["Літній вітер повернувся","Розбуди вітер","Вітер глибоко вдихає і дме по всьому небу.","Усі змії королівства злітають разом.","#7a4fa0"],["Парад зміїв","Приєднайся до параду","Королівство влаштовує свій найдовший парад зміїв, щоб подякувати Тонові.","Змії з усіх міст разом складаються у веселку.","#7a4fa0"],["Назад униз","Повернися на землю","Теплий вітерець лагідно опускає Тона вниз.","Друзі радіють, коли всі змії знову літають.","#7a4fa0"],["Змії для всіх","Поділися небом","Тон навчає друзів робити власних зміїв, і небо наповнюється барвами.","Те, що ми робимо руками й серцем, може віднести нас далеко. Кінець.","#7a4fa0"]]},"images":["kite-art/chapter-1.webp","kite-art/chapter-2.webp","kite-art/chapter-3.webp","kite-art/chapter-4.webp","kite-art/chapter-5.webp","kite-art/chapter-6.webp","kite-art/chapter-7.webp","kite-art/chapter-8.webp","kite-art/chapter-9.webp","kite-art/chapter-10.webp","kite-art/chapter-11.webp","kite-art/chapter-12.webp","kite-art/chapter-13.webp","kite-art/chapter-14.webp","kite-art/chapter-15.webp","kite-art/chapter-16.webp"],"cover":"kite-art/chapter-1.webp","descriptions":{"th":"ขึ้นไปยังอาณาจักรบนลม เพื่อซ่อมสายลมหน้าร้อนที่ขาด","en":"Fly to a kingdom on the wind and mend the broken summer breeze","es":"Vuela a un reino en el viento y repara la brisa del verano","zh":"飞到风中的王国，修好夏天的微风","ja":"風の上の王国へ飛んで、夏のそよ風をなおそう","ko":"바람 위의 왕국으로 날아가 여름 산들바람을 고쳐요","vi":"Bay đến vương quốc trên gió và sửa lại làn gió mùa hè","id":"Terbang ke kerajaan di atas angin dan perbaiki angin musim panas","ms":"Terbang ke kerajaan di atas angin dan baiki bayu musim panas","fil":"Lumipad sa kaharian sa hangin at ayusin ang simoy ng tag-araw","hi":"हवा पर बसे राज्य तक उड़ो और गर्मियों की हवा ठीक करो","ar":"طِر إلى مملكة فوق الريح وأصلح نسيم الصيف","fr":"Vole jusqu’à un royaume dans le vent et répare la brise d’été","de":"Flieg in ein Königreich im Wind und flicke die Sommerbrise","it":"Vola in un regno nel vento e ripara la brezza d’estate","pt":"Voe até um reino no vento e conserte a brisa do verão","ru":"Улети в королевство на ветру и почини летний ветерок","tr":"Rüzgârdaki bir krallığa uç ve yaz meltemini onar","pl":"Poleć do królestwa na wietrze i napraw letnią bryzę","nl":"Vlieg naar een rijk op de wind en repareer de zomerbries","uk":"Полети до королівства на вітрі й полагодь літній вітерець"}};
